package main

import (
	"net/http"
)

func (s *Server) home(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = w.Write([]byte(homeHTML))
}
func (s *Server) stylesheet(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/css; charset=utf-8")
	_, _ = w.Write([]byte(appCSS))
}
func (s *Server) script(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/javascript; charset=utf-8")
	_, _ = w.Write([]byte(appJS))
}

const homeHTML = `<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title>ModelAtlas</title><link rel="stylesheet" href="/app.css"></head>
<body><div class="shell"><header><div class="brand"><span class="mark" aria-hidden="true">M</span><div><strong>ModelAtlas</strong><small>探索模型，掌握每次回應。</small></div></div><button id="settings-toggle" class="ghost" type="button" aria-controls="settings">設定</button></header><main><p id="notice" role="status" aria-live="polite"></p>
<section id="playground" class="pane" aria-labelledby="playground-title"><div class="heading"><h1 id="playground-title">Playground</h1><p>選一個模型，開始對話。</p></div><div class="card chat-card"><div class="toolbar"><label>使用的模型<select id="target"></select></label><button id="new-session" class="ghost" type="button">新對話</button></div><details><summary>先前對話</summary><label>對話<select id="session"></select></label></details><div id="chat" class="chat" role="log" aria-live="polite"></div><div id="attachments" class="attachments"></div><form id="send-form"><label for="prompt" class="sr-only">訊息</label><textarea id="prompt" rows="3" maxlength="32000" required placeholder="想聊些什麼？"></textarea><div class="toolbar composer-tools"><div class="attachment-buttons"><label class="file-button">圖片<input id="image-picker" type="file" accept="image/png,image/jpeg,image/webp"></label><label class="file-button">PDF<input id="pdf-picker" type="file" accept="application/pdf"></label><label class="file-button">音訊<input id="audio-picker" type="file" accept="audio/wav,audio/mpeg,.wav,.mp3"></label></div><button id="stop" type="button" class="ghost" hidden>停止</button><button id="send">傳送</button></div></form></div></section>
<section id="providers" class="pane" hidden aria-labelledby="providers-title"><div class="heading"><h1 id="providers-title">Providers</h1><p>你的供應商與帳戶。</p></div><label class="search-label">搜尋 Provider<input id="provider-search" type="search" placeholder="名稱或網址"></label><div id="provider-list" class="cards"></div><details class="card"><summary>新增 Provider</summary><form id="onboarding-form"><label>名稱<input name="name" maxlength="120" required></label><label>API Base URL<input name="base_url" type="url" placeholder="https://example.com/v1" required></label><label>API Key<input name="secret" type="password" autocomplete="off"></label><label>Model ID（選填）<input name="model_id" placeholder="可貼上未列於 Catalog 的模型"></label><details><summary>進階設定</summary><label>Adapter<select name="adapter"><option value="GENERIC">自動 / OpenAI 相容</option><option>NEW_API</option><option>OPENROUTER_FREE</option><option>NVIDIA_NIM_HOSTED</option><option>NVIDIA_NIM_SELF_HOSTED</option><option>AMD_SHARED</option><option>AMD_DEDICATED</option><option>GEMINI_FREE</option><option>GROQ_FREE</option></select></label><label>認證<select name="auth_mode"><option>BEARER</option><option>API_KEY</option><option>CUSTOM_HEADER</option><option>NONE</option></select></label><label>自訂 Key Header<input name="auth_header" placeholder="x-api-key"></label><label>自訂 Key Query<input name="auth_query"></label><label>額外認證欄位 JSON（選填）<textarea name="auth_fields" placeholder='[{"name":"x-token","secret":"...","query":false}]'></textarea></label><label>帳戶名称<input name="account_label" value="主要帳戶"></label><label>Key 所屬 Group<input name="group"></label><label>Chat 路徑（選填）<input name="chat_path" placeholder="/v1/chat/completions"></label><label>官網<input name="website" type="url"></label><label>簽到網址<input name="checkin_url" type="url"></label><label>New API 帳戶 PAT（選填）<input name="pat" type="password" autocomplete="off"></label></details><button>檢查並預覽</button></form></details><details class="card"><summary>批次匯入</summary><form id="import-form"><label>Provider 設定 JSON<textarea name="json" rows="5" required placeholder='{"items":[...]}'></textarea></label><button>建立待確認清單</button></form><div id="onboarding-list" class="cards"></div></details></section>
<section id="models" class="pane" hidden aria-labelledby="models-title"><div class="heading"><h1 id="models-title">Models</h1><p>你明確加入的模型。</p></div><label>搜尋<input id="model-search" type="search" placeholder="名稱、別名或模型 ID"></label><details id="model-filters"><summary>篩選模型</summary><div class="toolbar"><label>顯示<select id="model-lifecycle"><option value="ACTIVE">使用中</option><option value="HIDDEN">已隱藏</option><option value="ARCHIVED">已封存</option></select></label></div><div class="toolbar"><label>能力<select id="model-capability"><option value="">全部</option><option>VISION</option><option>FILES</option><option>AUDIO_INPUT</option><option>CODING</option><option>REASONING</option><option>TOOL_CALLING</option></select></label><label>價格<select id="model-price"><option value="">全部</option><option value="FREE_NOW">FREE NOW</option><option value="UNKNOWN">尚未確認</option></select></label><label>收藏<select id="model-favorites"><option value="">全部</option><option value="favorite">最愛</option><option value="watchlist">追蹤</option></select></label></div><label>Provider<select id="model-provider"><option value="">全部</option></select></label></details><div id="my-models" class="cards"></div><button id="compare" class="ghost" type="button">比較勾選的模型</button><div id="compare-result"></div><details class="card"><summary>探索 Catalog</summary><label>搜尋 Catalog<input id="catalog-search" type="search"></label><div id="catalog" class="cards"></div><form id="model-form"><h2>手動加入模型</h2><label>連線<select name="selection" id="manual-target"></select></label><label>Model ID<input name="model_id" required></label><label>顯示名稱<input name="display_name" required></label><button>加入 My Models</button></form></details></section>
<section id="settings" class="pane" hidden aria-labelledby="settings-title"><div class="heading"><h1 id="settings-title">設定</h1><p>資料與同步偏好。</p></div><div class="card"><form id="settings-form"><label>效能時間窗<select name="performance_window"><option>1h</option><option>24h</option><option selected>7d</option><option>30d</option><option value="all">全部</option></select></label><label>時區<input name="timezone" value="Asia/Taipei" required></label><label class="check"><input name="notifications" type="checkbox">啟用本機通知</label><button>儲存設定</button></form><p>觀測與歷史持續保留。</p><a class="link-button" href="/api/v1/backup" download>匯出設定（不含 Key）</a><details><summary>還原設定</summary><form id="restore-form"><label>設定 JSON<textarea name="json" required></textarea></label><label class="check"><input name="confirm" type="checkbox" required>確認匯入（Key 需要重新輸入）</label><button>還原設定</button></form></details></div><div class="card"><h2>LMSpeed</h2><p>外部資料與你的實測分開保存。<a href="https://lmspeed.net" target="_blank" rel="noopener noreferrer">資料來源</a></p><form id="lmspeed-form"><label>LMSpeed 公開 API Key<input name="secret" type="password" autocomplete="off" required></label><button>儲存 Key</button></form><button id="lmspeed-sync" class="ghost" type="button">同步外部資料</button></div><details class="card"><summary>同步與研究紀錄</summary><div id="sync-history"></div><pre id="research"></pre></details><details class="card"><summary>最近請求</summary><div id="telemetry"></div></details><p id="status"></p></section>
</main><nav class="bottom-nav" aria-label="主分頁"><button data-tab="playground" class="active" aria-current="page">Playground</button><button data-tab="providers">Providers</button><button data-tab="models">Models</button></nav></div>
<dialog id="detail"><div class="dialog-bar"><h2 id="detail-title"></h2><button id="detail-close" class="ghost" type="button" aria-label="關閉詳情">關閉</button></div><div id="detail-content"></div></dialog><dialog id="review"><div class="dialog-bar"><h2>確認新增</h2><button id="review-close" class="ghost" type="button">關閉</button></div><form id="review-form"><div id="review-content"></div><button>確認並加入</button></form></dialog><script src="/app.js" defer></script></body></html>`
